/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, CompanionMatrix, DotProduct, Float, LofLU, Matrix, MatrixSet, MatrixSymbol, Mul, Poly, Pow, Q, QofQR, Reals, RofQR, S, SofSVD, Sym, UofLU, UofSVD, VofSVD, add, ask, interval, isUnsolved, mul, oo, pow, rational, str, symbols, unchanged } from '../../../src';
import { at, sympyMatches, sympyStr } from '../../sympy-str';

describe("doctests of sympy.matrices.expressions.dotproduct", () => {
  it("DotProduct(A, B)", () => {
    expect(sympyStr(DotProduct(new MatrixSymbol('A', rational(1), rational(3)), new MatrixSymbol('B', rational(1), rational(3))))).toBe('DotProduct(A, B)');
  });
  it("DotProduct(A, B).doit()", () => {
    expect(sympyStr(DotProduct(new MatrixSymbol('A', rational(1), rational(3)), new MatrixSymbol('B', rational(1), rational(3))).doit())).toBe('A[0, 0]*B[0, 0] + A[0, 1]*B[0, 1] + A[0, 2]*B[0, 2]');
  });
});

describe("doctests of sympy.matrices.expressions.companion", () => {
  it("CompanionMatrix(p)", () => {
    const [c0, x, c1, c2, c3, c4] = symbols('c0 x c1 c2 c3 c4');
    expect(sympyStr(CompanionMatrix(Poly.from(add(c0, pow(x, 5), mul(c1, x), mul(c2, pow(x, 2)), mul(c3, pow(x, 3)), mul(c4, pow(x, 4))), [x], { domain: 'ZZ[c0,c1,c2,c3,c4]', pure: false })))).toBe('CompanionMatrix(Poly(x**5 + c4*x**4 + c3*x**3 + c2*x**2 + c1*x + c0, x, domain=\'ZZ[c0,c1,c2,c3,c4]\'))');
  });
});

describe("doctests of sympy.matrices.expressions.sets", () => {
  it("X in M", () => {
    expect(sympyStr(MatrixSet(rational(2), rational(2), Reals).contains(Matrix.of([[rational(1), rational(2)], [rational(3), rational(4)]])))).toBe('True');
  });
  it("X in M (2)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
});

