describe("sympy/matrices/expressions/tests/test_sets.py", () => {
  it("test_MatrixSet:19", () => {
    expect(sympyMatches([rational(2), rational(2)], '(2, 2)')).toBe(true);
  });
  it("test_MatrixSet:20", () => {
    expect(sympyStr(interval(S.NegativeInfinity, oo, true, true))).toBe('Reals');
  });
  it.fails("test_MatrixSet:25", () => {
    expect(() => str(MatrixSet(rational(2), rational(2), Reals))).toThrow(TypeError);
  });
  it("test_MatrixSet:26", () => {
    expect(() => MatrixSet(rational(2), rational(2), Reals).contains(rational(1))).toThrow(TypeError);
  });
  it.fails("test_MatrixSet:29", () => {
    const n = new Sym('n', { integer: true });
    const m = new Sym('m', { integer: true });
    expect(() => str(MatrixSet(n, m, Reals))).toThrow(TypeError);
  });
  it.fails("test_MatrixSet:30", () => {
    const n = new Sym('n', { integer: true });
    const m = new Sym('m', { integer: true });
    expect(() => str(MatrixSet(n, m, Reals))).toThrow(TypeError);
  });
  it("test_MatrixSet:34", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("test_MatrixSet:35", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("test_MatrixSet:36", () => {
    expect(() => MatrixSet(rational(2), rational(-2), Reals)).toThrow(RangeError);
  });
  it("test_MatrixSet:37", () => {
    expect(() => MatrixSet(new Float(2.4), rational(-1), Reals)).toThrow(RangeError);
  });
  it.fails("test_MatrixSet:38", () => {
    expect(() => str(rational(2))).toThrow(TypeError);
  });
});
